/**
 * What a finger movement means. Pure arithmetic, no DOM.
 *
 * Gestures are invisible: nothing on screen says that dragging sideways changes the speed, so
 * getting the thresholds wrong is not a cosmetic problem — it is the difference between a
 * control that works and one the operator concludes is broken. Keeping the decisions here,
 * away from the pointer plumbing, is what makes them testable at all.
 */

import { MAX_VOLUME, MIN_VOLUME } from '../core/volume.js';

/**
 * Below this, a finger that moved is still a tap. Thumbs are never perfectly still: a thumb
 * covers something like 40 pixels of glass, and it rolls as it lifts. Set this too tight and
 * an ordinary tap is read as a drag, which does not play or pause — it quietly changes the
 * volume instead, and the tap looks like it was ignored.
 */
export const TAP_SLOP_PX = 24;

/** How far sideways one speed step costs. Roughly a thumb's width on a phone. */
export const SPEED_STEP_PX = 64;

/** A slow drag gets fine control; a quick drag crosses more of the value range. */
export const SLOW_SWIPE_PX_MS = 0.25;
export const FAST_SWIPE_PX_MS = 1;
export const SLOW_SWIPE_GAIN = 0.5;
export const FAST_SWIPE_GAIN = 1.5;

export function swipeGainFor(velocity: number): number {
  if (!Number.isFinite(velocity) || velocity < 0) return 1;
  const share = Math.min(
    1,
    Math.max(0, (velocity - SLOW_SWIPE_PX_MS) / (FAST_SWIPE_PX_MS - SLOW_SWIPE_PX_MS)),
  );
  return SLOW_SWIPE_GAIN + share * (FAST_SWIPE_GAIN - SLOW_SWIPE_GAIN);
}

/**
 * How far the intended direction must beat the other one before a drag counts.
 *
 * At 1.5 a drag has to stay inside about 34 degrees of level or upright; between 34 and 56
 * degrees nothing happens at all. That dead wedge is the point, and the operator asked for it
 * on 2026-09-22: until then the larger movement simply won, so a drag at 46 degrees — which
 * the hand cannot tell apart from one at 44 — changed the volume instead of the speed. One
 * gesture silently becoming the other is worse than neither of them firing, because the
 * wrong one has already happened by the time it is noticed.
 */
const AXIS_DOMINANCE = 1.5;

export type DragKind = 'horizontal' | 'vertical' | 'none';

/**
 * Which way the finger is going, or nothing when it is going neither way clearly.
 */
export function classifyDrag(dx: number, dy: number): DragKind {
  const across = Math.abs(dx);
  const down = Math.abs(dy);
  if (across <= TAP_SLOP_PX && down <= TAP_SLOP_PX) return 'none';
  if (across >= down * AXIS_DOMINANCE) return 'horizontal';
  if (down >= across * AXIS_DOMINANCE) return 'vertical';
  return 'none';
}

/**
 * The axis a drag is on: whatever it was already on, or the first clear answer.
 *
 * Re-deciding this on every move is what made a drag change the speed and then silently
 * switch to changing the volume — a thumb pivoting from a knuckle curves on its own, and
 * rejecting the diagonal in the middle does not help, because the hand crosses the dead
 * wedge and comes out the far side looking like a clean drag along the other axis.
 * Answering `null` means nothing is decided yet and the caller should leave both alone.
 */
export function lockedDragKind(locked: DragKind | null, dx: number, dy: number): DragKind | null {
  if (locked !== null) return locked;
  const kind = classifyDrag(dx, dy);
  return kind === 'none' ? null : kind;
}

/** Whole speed steps earned by a sideways drag, right for faster. */
export function speedStepsFor(dx: number): number {
  if (!Number.isFinite(dx)) return 0;
  // `|| 0` turns a leftward drag that earned nothing from -0 into 0, so callers comparing
  // against a previous count of 0 are not left wondering why two zeroes differ.
  return Math.trunc(dx / SPEED_STEP_PX) || 0;
}

/**
 * The volume a vertical drag lands on. Up is louder, and dragging the full height of the
 * picture covers the whole range — so the gesture means the same thing on any screen.
 */
export function volumeFor(startVolume: number, dy: number, height: number): number {
  if (!Number.isFinite(dy) || !Number.isFinite(height) || height <= 0) return startVolume;
  const moved = (-dy / height) * (MAX_VOLUME - MIN_VOLUME);
  return Math.min(MAX_VOLUME, Math.max(MIN_VOLUME, Math.round(startVolume + moved)));
}

export type Zone = 'left' | 'centre' | 'right';

/** Which third of the picture a point falls in. */
export function zoneOf(x: number, width: number): Zone {
  if (!Number.isFinite(x) || !Number.isFinite(width) || width <= 0) return 'centre';
  if (x < width / 3) return 'left';
  if (x >= (width * 2) / 3) return 'right';
  return 'centre';
}

/**
 * Whose sound a gesture in this third of the picture acts on (operator, 2026-09-24).
 *
 * With two slots the thirds are split by name: left is 動画 (slot 0), right is 音楽 (slot 1),
 * the middle both — whichever of the two is on screen. Watching one while the other plays
 * behind it, the one behind is exactly the one whose own controls are out of reach. With one
 * slot, or with the wall, there is no named pair, so every third is the picture being watched.
 * Used for both the vertical drag (volume) and the double tap (mute).
 */
export function soundOwnersFor(slotCount: number, expanded: number, zone: Zone): number[] {
  if (slotCount !== 2) return [expanded];
  if (zone === 'left') return [0];
  if (zone === 'right') return [1];
  return [0, 1];
}

/**
 * Which job a sideways drag does, by where it started: the top half moves through the video,
 * the bottom half changes the speed (operator, 2026-09-24).
 */
export function horizontalJobFor(y: number, height: number): 'scrub' | 'speed' {
  if (!Number.isFinite(y) || !Number.isFinite(height) || height <= 0) return 'speed';
  return y < height / 2 ? 'scrub' : 'speed';
}

/** A drag across the whole picture moves this far through the video, or the whole video. */
export const SCRUB_SPAN_SECONDS = 120;

/**
 * How many seconds a sideways drag in the top half moves by. Right is forward.
 *
 * The whole width is two minutes, or the whole video when it is shorter than that — so a
 * 40-second short can be crossed end to end, and a two-hour film is not flung an hour by a
 * nervous thumb.
 */
export function scrubSecondsFor(dx: number, width: number, length: number): number {
  if (!Number.isFinite(dx) || !Number.isFinite(width) || width <= 0) return 0;
  const span =
    Number.isFinite(length) && length > 0
      ? Math.min(SCRUB_SPAN_SECONDS, length)
      : SCRUB_SPAN_SECONDS;
  return Math.round((dx / width) * span) || 0;
}

/**
 * What a two-finger squeeze or spread asks for. The dead band in the middle is deliberate:
 * two fingers never land and lift at exactly the same distance apart.
 */
export function pinchIntent(scale: number): 'fill' | 'fit' | 'none' {
  if (!Number.isFinite(scale) || scale <= 0) return 'none';
  // A larger change than before is needed, so an ordinary two-finger landing does nothing.
  if (scale >= 1.3) return 'fill';
  if (scale <= 0.77) return 'fit';
  return 'none';
}

/**
 * How far two fingers' midpoint must travel before the hand counts as a swipe, and how far
 * apart the fingers must spread or close before it counts as a squeeze.
 *
 * The swipe is quick to decide and the squeeze slow (operator, 2026-09-24: ピンチの反応が
 * 早すぎる・2 本指スワイプは反応が遅い). The two answer different evidence, which is what keeps
 * them apart: a swipe moves both fingers the same way, so the midpoint travels while the gap
 * barely changes; a squeeze moves them against each other, so the gap changes while the
 * midpoint, at most, drifts half as far.
 */
export const PAN_LOCK_PX = 14;
export const PINCH_LOCK_PX = 48;

export type TwoFingerKind = 'pan' | 'pinch';

/**
 * What two fingers are doing, or nothing yet. Decided once per gesture by the caller and held:
 * a swipe that has started never turns into a squeeze on the way (operator, 2026-09-24:
 * 2 本指スワイプ時にピンチ操作が作動する).
 *
 * `spreadChange` is how much the gap between the fingers has changed, in pixels; `travel`
 * is how far their midpoint has moved.
 */
export function classifyTwoFinger(spreadChange: number, travel: number): TwoFingerKind | null {
  if (!Number.isFinite(spreadChange) || !Number.isFinite(travel)) return null;
  const spread = Math.abs(spreadChange);
  if (travel >= PAN_LOCK_PX && travel >= spread * 1.2) return 'pan';
  if (spread >= PINCH_LOCK_PX && spread >= travel * 1.5) return 'pinch';
  return null;
}

/** Which way a swipe runs, decided when it starts and kept until the hand lifts. */
export function panAxisFor(dx: number, dy: number): 'x' | 'y' {
  return Math.abs(dx) >= Math.abs(dy) ? 'x' : 'y';
}

/** A swipe past this share of the screen goes through when the hand lifts. */
export const SWIPE_COMMIT_SHARE = 0.3;
/** A flick this fast goes through however short it was — about a finger's width in a blink. */
export const FLICK_SPEED = 0.5;
/** …as long as it went at least this far. A twitch is not a flick. */
export const FLICK_MIN_PX = 40;

/**
 * Whether a swipe that followed the hand goes through when it lifts, or springs back.
 *
 * The picture moves with the fingers from the start, so a swipe begun by accident shows
 * itself and costs nothing: let go early and it slides back (operator, 2026-09-24: 少し
 * スワイプで動き始めて離したら元の画面・続けたら隣の画面). Past a third of the screen it goes
 * through; so does a quick flick in the direction it was moving, the way a photo album turns.
 */
export function swipeCommits(delta: number, size: number, velocity: number): boolean {
  if (!Number.isFinite(delta) || !Number.isFinite(size) || !Number.isFinite(velocity)) {
    return false;
  }
  if (size > 0 && Math.abs(delta) >= size * SWIPE_COMMIT_SHARE) return true;
  return (
    Math.abs(delta) >= FLICK_MIN_PX &&
    Math.abs(velocity) >= FLICK_SPEED &&
    Math.sign(velocity) === Math.sign(delta)
  );
}

/** How far back a flick is measured: long enough to average out jitter, short enough to be now. */
export const FLICK_WINDOW_MS = 100;

export interface Sample {
  /** Milliseconds, from any one clock. */
  readonly t: number;
  /** Position along the swipe, in pixels. */
  readonly v: number;
}

/** Speed at the end of a run of samples, in pixels per millisecond. 0 when it cannot tell. */
export function velocityOf(samples: readonly Sample[]): number {
  const last = samples[samples.length - 1];
  if (last === undefined) return 0;
  const first = samples.find((sample) => last.t - sample.t <= FLICK_WINDOW_MS) ?? last;
  const dt = last.t - first.t;
  return dt > 0 ? (last.v - first.v) / dt : 0;
}

/**
 * How much to enlarge the picture so it covers a differently shaped screen, given both
 * shapes as width divided by height. Always at least 1: filling never shrinks anything.
 */
export function fillScaleFor(videoRatio: number, frameRatio: number): number {
  if (!Number.isFinite(videoRatio) || !Number.isFinite(frameRatio)) return 1;
  if (videoRatio <= 0 || frameRatio <= 0) return 1;
  return Math.max(1, frameRatio / videoRatio, videoRatio / frameRatio);
}
