/**
 * Getting a read-only YouTube token, from the browser alone.
 *
 * There is no server in this app, so there is nowhere to keep a client secret or a refresh
 * token — and that is fine: Google Identity Services hands a short-lived access token straight
 * to the page. The token lives in memory only. Putting it in localStorage would leave it
 * sitting on the device long after the tab closed, for a convenience that `trySilent` already
 * provides: if the operator is signed in to Google and has consented before, a fresh token
 * arrives with no popup and no tap.
 *
 * Nothing here blocks playback. Every failure path ends in "no token", and the app keeps
 * working exactly as it did before anyone signed in.
 *
 * Two rules exist because of one message the operator saw on 2026-09-21 — 「ポップアップが
 * ブロックされました」:
 *
 * 1. **Google's script is fetched before the tap, not during it.** A browser only lets a page
 *    open a window while it is still handling a real tap, and awaiting a network request in
 *    the middle of that spends the permission. `prime()` starts the fetch on the first touch
 *    anywhere on the page, so by the time anyone finds the sign-in button it is already there.
 * 2. **`trySilent` is only tried when this device has consented before.** Google's "silent"
 *    request is not silent when consent is missing: it opens the consent window, and doing
 *    that on page load — with no tap at all — is exactly what a popup blocker exists to stop.
 *    A note in local storage remembers that consent happened here. It is a hint, never a
 *    credential; the worst a tampered one can do is make the app try and fail once.
 */

import { GOOGLE_CLIENT_ID, YOUTUBE_SCOPE } from '../config.js';

const GIS_SRC = 'https://accounts.google.com/gsi/client';
const SCRIPT_TIMEOUT_MS = 10_000;
const TOKEN_TIMEOUT_MS = 60_000;

/** Asking one minute early, so a request never starts with a token that expires mid-flight. */
const EXPIRY_MARGIN_MS = 60_000;

interface TokenResponse {
  readonly access_token?: string;
  readonly expires_in?: number;
  readonly error?: string;
}

interface TokenClient {
  requestAccessToken(overrides?: { prompt?: string }): void;
}

interface TokenClientConfig {
  readonly client_id: string;
  readonly scope: string;
  readonly callback: (response: TokenResponse) => void;
  readonly error_callback?: (error: { type?: string }) => void;
}

interface GisNamespace {
  readonly accounts: {
    readonly oauth2: {
      initTokenClient(config: TokenClientConfig): TokenClient;
      revoke(token: string, done?: () => void): void;
    };
  };
}

declare global {
  interface Window {
    google?: GisNamespace;
  }
}

/** Not a credential — only a note that the consent window has been through once here. */
const CONSENTED_KEY = 'yt-dual.google.consented';
/** Why the note above was last dropped. Kept for diagnosis; nothing reads it to decide. */
const FORGOTTEN_KEY = 'yt-dual.google.consent-forgotten';

/**
 * The words Google uses when the operator would genuinely have to be asked again: consent
 * withdrawn, a different account, a session that has ended.
 *
 * Anything else — a script that did not load, a request that timed out, a network that was
 * down for a moment — says nothing about consent, and must not be treated as if it did.
 * Forgetting on those turns one bad minute into "sign in by hand from now on", which is the
 * failure the operator reported on 2026-09-21 as 「ログインしたままにできない」.
 */
const CONSENT_GONE = new Set([
  'access_denied',
  'consent_required',
  'interaction_required',
  'login_required',
  'invalid_grant',
  'invalid_client',
]);

/**
 * Whether a silent-sign-in failure means the consent itself is gone.
 *
 * Unknown failures answer `false`. Getting it wrong in that direction costs one blocked popup
 * the next time the app opens; getting it wrong the other way costs every sign-in from here
 * on, which is much worse and much harder to notice.
 */
export function isConsentGone(error: unknown): boolean {
  return error instanceof Error && CONSENT_GONE.has(error.message);
}

function readConsented(): boolean {
  try {
    return window.localStorage.getItem(CONSENTED_KEY) === '1';
  } catch {
    // Blocked site data: treat it as "never consented" and ask with a real tap.
    return false;
  }
}

function writeConsented(value: boolean): void {
  try {
    if (value) {
      window.localStorage.setItem(CONSENTED_KEY, '1');
      window.localStorage.removeItem(FORGOTTEN_KEY);
    } else {
      window.localStorage.removeItem(CONSENTED_KEY);
    }
  } catch {
    // Remembering is a convenience; sign-in still works without it.
  }
}

/**
 * Leaves behind why signing in stopped being automatic.
 *
 * Without it, the only evidence is the operator noticing they were asked to sign in again,
 * long after the reason has gone — and every cause looks identical from there.
 */
function rememberWhyForgotten(reason: string): void {
  try {
    window.localStorage.setItem(FORGOTTEN_KEY, `${new Date().toISOString()} ${reason}`);
  } catch {
    // Diagnosis is a convenience too.
  }
}

let scriptPromise: Promise<GisNamespace> | null = null;

/** Loaded on demand: someone who never signs in should never fetch Google's script. */
function loadGis(): Promise<GisNamespace> {
  if (scriptPromise !== null) return scriptPromise;

  scriptPromise = new Promise<GisNamespace>((resolve, reject) => {
    const existing = window.google;
    if (existing !== undefined) {
      resolve(existing);
      return;
    }

    const script = document.createElement('script');
    script.src = GIS_SRC;
    script.async = true;

    const timer = setTimeout(() => {
      reject(new Error('Google のスクリプトが時間内に届きませんでした'));
    }, SCRIPT_TIMEOUT_MS);

    script.addEventListener('load', () => {
      clearTimeout(timer);
      const loaded = window.google;
      if (loaded === undefined) {
        reject(new Error('Google のスクリプトは届いたのに中身がありません'));
        return;
      }
      resolve(loaded);
    });
    script.addEventListener('error', () => {
      clearTimeout(timer);
      reject(new Error('Google のスクリプトを読み込めません'));
    });

    document.head.appendChild(script);
  });

  // A failed load must not be cached, or a flaky network would disable sign-in for the session.
  scriptPromise.catch(() => {
    scriptPromise = null;
  });

  return scriptPromise;
}

/**
 * Google reports its refusals as short machine words. Two of them have very different
 * answers for the operator, and both used to arrive as the same "could not sign in".
 */
export function describeSignInFailure(error: unknown): string {
  const reason = error instanceof Error ? error.message : '';
  if (reason === 'popup_failed_to_open') {
    return 'ログインの窓が開けませんでした。ブラウザの設定でこの画面のポップアップを許可してから、もう一度押してください。';
  }
  if (reason === 'popup_closed') return 'ログインの窓が閉じられました。';
  if (reason === 'access_denied') return 'ログインが許可されませんでした。';
  return 'ログインできませんでした。';
}

export class GoogleAuth {
  #token: string | null = null;
  #expiresAt = 0;
  #client: TokenClient | null = null;
  #pending: ((response: TokenResponse | Error) => void) | null = null;

  /** The token we already hold, if it is still good. Never triggers a network call. */
  currentToken(): string | null {
    if (this.#token === null) return null;
    return Date.now() + EXPIRY_MARGIN_MS < this.#expiresAt ? this.#token : null;
  }

  isSignedIn(): boolean {
    return this.currentToken() !== null;
  }

  /**
   * Starts fetching Google's script, without asking for anything. Call it on a first touch,
   * well before the sign-in tap: the tap itself has no time to wait for a network request.
   */
  prime(): void {
    void loadGis().catch(() => {
      // Nothing to report: sign-in will try again and say so properly if it still fails.
    });
  }

  /** True once the consent window has succeeded on this device. */
  hasConsented(): boolean {
    return readConsented();
  }

  /** Whether the script is here, so the tap can open the window without waiting. */
  isReady(): boolean {
    return window.google !== undefined;
  }

  /** Shows Google's consent screen. Must be called from a real tap, or the popup is blocked. */
  async signIn(): Promise<string> {
    const token = await this.#request('consent');
    writeConsented(true);
    return token;
  }

  /**
   * Tries without showing anything. Returns null when the operator would have to be asked —
   * not signed in to Google, never consented, or consent withdrawn.
   *
   * Refuses outright when this device has not consented before, because Google's "silent"
   * request opens the consent window in that case and there is no tap behind this call.
   */
  async trySilent(): Promise<string | null> {
    const held = this.currentToken();
    if (held !== null) return held;
    if (!readConsented()) return null;
    try {
      return await this.#request('');
    } catch (error) {
      // Only a refusal about consent itself is worth forgetting over. A failure to reach
      // Google says nothing about whether consent still stands, and the next attempt costs
      // nothing — while forgetting costs a manual sign-in every time from here on.
      if (isConsentGone(error)) {
        writeConsented(false);
        rememberWhyForgotten(error instanceof Error ? error.message : String(error));
      }
      return null;
    }
  }

  /**
   * Drops the note that this device has consented.
   *
   * For the one case `trySilent` cannot see: a token that was fetched successfully and then
   * turned away by YouTube itself. Consent is evidently not what it was, and without this the
   * button would keep saying 一覧 with no way left to sign in by hand.
   */
  forgetConsent(): void {
    writeConsented(false);
    rememberWhyForgotten('youtube-refused');
  }

  signOut(): void {
    const token = this.#token;
    this.#token = null;
    this.#expiresAt = 0;
    writeConsented(false);
    if (token === null) return;
    void loadGis().then((gis) => {
      gis.accounts.oauth2.revoke(token);
    });
  }

  async #request(prompt: string): Promise<string> {
    const gis = await loadGis();
    const client = this.#ensureClient(gis);

    const response = await new Promise<TokenResponse | Error>((resolve) => {
      const timer = setTimeout(() => {
        resolve(new Error('Google からの返事がありません'));
      }, TOKEN_TIMEOUT_MS);

      this.#pending = (result) => {
        clearTimeout(timer);
        resolve(result);
      };

      client.requestAccessToken({ prompt });
    });

    this.#pending = null;

    if (response instanceof Error) throw response;
    if (typeof response.error === 'string') throw new Error(response.error);

    const token = response.access_token;
    if (typeof token !== 'string' || token.length === 0) {
      throw new Error('Google がトークンを返しませんでした');
    }

    const seconds = typeof response.expires_in === 'number' ? response.expires_in : 3600;
    this.#token = token;
    this.#expiresAt = Date.now() + seconds * 1000;
    return token;
  }

  /** One client for the life of the page; GIS expects it to be reused, not rebuilt per request. */
  #ensureClient(gis: GisNamespace): TokenClient {
    if (this.#client !== null) return this.#client;

    this.#client = gis.accounts.oauth2.initTokenClient({
      client_id: GOOGLE_CLIENT_ID,
      scope: YOUTUBE_SCOPE,
      callback: (response) => {
        this.#pending?.(response);
      },
      error_callback: (error) => {
        this.#pending?.(new Error(error.type ?? 'ログインを中断しました'));
      },
    });

    return this.#client;
  }
}
