/**
 * What shape the video actually is.
 *
 * A short is 9:16 and an ordinary video is 16:9. A frame fixed at 16:9 shows the first as a
 * postage stamp between two black walls — most of the screen spent on nothing. So the frame
 * takes the video's own shape instead.
 *
 * How it is read: YouTube publishes a thumbnail cut to the video's own proportions at
 * `i.ytimg.com/vi/<id>/frame0.jpg`, and a browser may read any image's natural size across
 * origins. So one small picture (1 KB for a wide video, 24 KB for a tall one — measured
 * 2026-09-20) answers the question with no API key, no sign-in and no quota at all. The other
 * routes all cost something: the Data API charges quota and needs a token, and `oembed`
 * answers 200x113 for every video whatever its shape (also measured — it reports the default
 * player size, not the video).
 *
 * Not every video has one. Live streams answer 404, so **every** failure path lands on 16:9,
 * which is exactly what the frame did before this file existed. Nothing here can make the
 * player worse than it was; the worst case is that it fails to improve.
 */

/** Width divided by height. CSS `aspect-ratio` takes this single number directly. */
export const DEFAULT_RATIO = 16 / 9;

/**
 * Past these the frame stops following the video. A pathological clip (1:10, or a 20:1
 * banner) would otherwise push the rest of the page off the screen, and no real video needs
 * more room than this.
 */
export const MIN_RATIO = 0.4;
export const MAX_RATIO = 3;

const PROBE_TIMEOUT_MS = 8000;

/** Takes a url, answers its width/height. Swapped out in tests; the real one needs a browser. */
export type RatioProbe = (url: string) => Promise<number>;

export function thumbnailUrl(videoId: string): string {
  return `https://i.ytimg.com/vi/${encodeURIComponent(videoId)}/frame0.jpg`;
}

export function clampRatio(ratio: number): number {
  if (!Number.isFinite(ratio) || ratio <= 0) return DEFAULT_RATIO;
  return Math.min(Math.max(ratio, MIN_RATIO), MAX_RATIO);
}

/**
 * The browser half. Untested by the suite on purpose: it is three lines of `Image` plumbing
 * that cannot run outside a browser, and everything worth getting wrong lives in `clampRatio`
 * and in the failure handling of `fetchVideoRatio`, which are both tested.
 */
function probeWithImage(url: string): Promise<number> {
  return new Promise<number>((resolve, reject) => {
    const image = new Image();

    // A thumbnail that never answers must not leave the frame waiting forever.
    const timer = setTimeout(() => {
      image.src = '';
      reject(new Error('thumbnail timed out'));
    }, PROBE_TIMEOUT_MS);

    image.addEventListener('load', () => {
      clearTimeout(timer);
      if (image.naturalHeight === 0) {
        reject(new Error('thumbnail has no size'));
        return;
      }
      resolve(image.naturalWidth / image.naturalHeight);
    });

    image.addEventListener('error', () => {
      clearTimeout(timer);
      reject(new Error('no thumbnail for this video'));
    });

    image.src = url;
  });
}

/** Never rejects. An unknown shape is not an error — it is 16:9, the same as always. */
export async function fetchVideoRatio(
  videoId: string,
  probe: RatioProbe = probeWithImage,
): Promise<number> {
  if (videoId === '') return DEFAULT_RATIO;
  try {
    return clampRatio(await probe(thumbnailUrl(videoId)));
  } catch {
    return DEFAULT_RATIO;
  }
}
